let padPointer=null;function padMove(e){const r=$('directionPad').getBoundingClientRect(),dx=(e.clientX-r.left-r.width/2)/(r.width*.32),dy=(e.clientY-r.top-r.height/2)/(r.height*.32),n=Math.max(1,Math.hypot(dx,dy));joystick={right:dx/n,forward:-dy/n};$('joystickKnob').style.transform=`translate(calc(-50% + ${joystick.right*34}px),calc(-50% + ${-joystick.forward*34}px))`}
