const keyDirections={w:'forward',s:'back',a:'left',d:'right',q:'turnLeft',e:'turnRight'};
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;const direction=keyDirections[e.key.toLowerCase()];if(direction){e.preventDefault();startManual(e.key.toLowerCase(),direction)}});document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();if(keyDirections[key]&&manualInputs.has(key)){e.preventDefault();stopManual(key)}});window.addEventListener('blur',()=>stopManual());
