function manualTick(dt){if(dt<=0)return false;const axes={forward:joystick.forward,right:joystick.right,turn:0};for(const v of manualInputs.values())for(const k of Object.keys(v))axes[k]+=v[k];axes.turn=Math.max(-1,Math.min(1,axes.turn));if(!axes.forward&&!axes.right&&!axes.turn)return false;const p=state.manualPosition,next=FlightControls.move(p,axes,dt),h=mission?.hazard;const blocked=h&&FlightControlsBlocked(p,next,h);if(state.battery<=0||blocked){if(!manualBlocked){toast(blocked?'前方为模拟限制区，请调整方向':'模拟电量耗尽，已悬停');log('manual_blocked','手动移动受限',blocked?'二维限制区':'电量耗尽');manualBlocked=true}state.manualPosition.heading=next.heading;state.manualSpeed=0;return true}state.manualPosition={x:next.x,y:next.y,heading:next.heading};state.manualSpeed=next.distance/dt;state.manualDistance=(state.manualDistance||0)+next.distance;state.simTime+=dt;const trail=state.trail||(state.trail=[]),end=trail.at(-1);if(!end||Math.hypot(end[0]-next.x,end[1]-next.y)>=1)trail.push([next.x,next.y]);return true}
