function checkCollision(a,target){if(state.status==='collision')return false;const p=currentPosition(),b={x:p.x,y:p.y,z:state.altitude},next=state.traffic?Traffic.position(state.traffic):null,hit=[window.worldCollision?.(a,b),Collision.detect(a,b,target?{x:target.x,y:target.y,z:target.altitude}:null,next?{x:next.x,y:next.y,z:next.altitude}:null)].filter(Boolean).sort((a,b)=>a.t-b.t)[0];if(!hit)return false;const before=snap();state.manualPosition={x:a.x+(b.x-a.x)*hit.t,y:a.y+(b.y-a.y)*hit.t,heading:p.heading};state.altitude=a.z+(b.z-a.z)*hit.t;state.targetAltitude=state.altitude;state.verticalSpeed=0;manualInputs.clear();joystick={forward:0,right:0};state.manualSpeed=0;state.status='collision';state.trail.push([state.manualPosition.x,state.manualPosition.y]);log('collision','发生实体碰撞',hit.label,before);toast('模拟碰撞：'+hit.label+'，飞行已停止');render();return true}
$('collisionTrial').onclick=()=>{if(!state.traffic||!state.conflictAlert)return;state.collisionExperiment=true;state.route=C.clone(mission.initialRoute);state.progress=0;state.status='running';mission.title='碰撞实验：保持原航线';mission.summary='已主动选择不避让，机体接触时将记录碰撞并停止。';log('collision_override','选择保持原航线','受控模拟实验');render()};
