$('waitTraffic').onclick=()=>{if(!state.traffic||!state.conflictAlert)return;state.route=C.clone(mission.initialRoute);state.progress=0;state.status='waiting';mission.title='悬停让行，等待目标通过';mission.summary='本机保持位置，交通目标继续运动；间隔恢复后可继续飞行。';log('accept','选择等待让行','保持位置，交通目标继续移动');render()};
function presentStage(index,resume=false){
 const before=snap(),position=currentPosition(),origin=resume?[position.x,position.y]:Sequence.points[index].point;
 if(Math.hypot(origin[0]-Sequence.points[index+1].point[0],origin[1]-Sequence.points[index+1].point[1])<3){toast('已在当前目标附近，请手动退开后重规划');return}
 const oldSequence=state.sequence||{},oldTraffic=resume?state.traffic:null,oldPhotoDone=resume&&state.photoCheckpointDone,rate=state.simRate||4;const next=Sequence.make(index,origin,state.battery),oldTime=state.simTime,trail=C.clone(state.trail),altitude=state.altitude,speed=state.speed;
 manualInputs.clear();joystick={forward:0,right:0};session.node=next.id;mission=next;draft=null;
 state={status:'review',sequence:{index,single:!!oldSequence.single},simRate:rate,route:C.clone(next.route),progress:0,altitude,targetAltitude:altitude,speed,battery:next.battery,simTime:oldTime,goalDeferred:false,trail,presentedAt:Date.now(),photoCheckpointDone:!!oldPhotoDone};
 $('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false');$('aiBody').hidden=false;$('toggleAI').textContent='−';$('toggleAI').setAttribute('aria-expanded','true');
 if(index===2){state.traffic=oldTraffic||Traffic.create(origin,next.destination.point,speed);$('pitch').value='20';$('pitchValue').textContent='−20°';window.flightView?.pitch?.(20)}$('simRate').value=String(rate);
 log('present',resume?'手动接管后重新规划':'触发连续航线事件',next.event,before);render();window.focusMissionRoute?.((state.sequence.single?Sequence.points.slice(index,index+2):Sequence.points).map(p=>p.point));
}
$('simRate').value=String(state.simRate||4);if(mission){$('destinationInput').value=mission.destination.name;$('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false')}render();if(mission)window.focusMissionRoute?.([...(state.trail||[]),...state.route]);requestAnimationFrame(tick);





window.addEventListener('world-ready',()=>render());
